import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.Dp0m3YJZ.js";const m=JSON.parse('{"title":"WUWAOS 實作紀錄","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),o={name:"index.md"};function i(h,t,l,s,n,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="wuwaos-實作紀錄" tabindex="-1">WUWAOS 實作紀錄 <a class="header-anchor" href="#wuwaos-實作紀錄" aria-label="Permalink to &quot;WUWAOS 實作紀錄&quot;">​</a></h1><p>從第一條指令，到能建立行程、編輯檔案的小型作業系統。</p><p>WUWAOS 是以 C 與 RISC-V 組合語言撰寫、真正運行於 QEMU 虛擬電腦上的作業系統。這份文件把設計按照主題整理，連接教科書觀念、目前程式碼與可以親手觀察的操作。</p><p><strong><a href="./topics/getting-started.html">從環境與啟動開始 →</a></strong></p><h2 id="閱讀路線" tabindex="-1">閱讀路線 <a class="header-anchor" href="#閱讀路線" aria-label="Permalink to &quot;閱讀路線&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想理解什麼</th><th>從這裡開始</th></tr></thead><tbody><tr><td>entry.S 怎麼進入 C，最後顯示提示字元？</td><td><a href="./topics/boot.html">開機流程</a></td></tr><tr><td>使用者程式怎麼請核心幫忙？</td><td><a href="./topics/traps.html">例外與系統呼叫</a></td></tr><tr><td>行程如何建立、排程、結束與回收？</td><td><a href="./topics/processes.html">行程管理</a> → <a href="./topics/scheduling.html">FIFO 排程</a></td></tr><tr><td>CPU 如何找到資料，缺頁時發生什麼？</td><td><a href="./topics/memory.html">Sv39</a> → <a href="./topics/paging.html">按需分頁與交換</a></td></tr><tr><td>輸入的文字如何存到磁碟？</td><td><a href="./topics/io.html">輸入輸出</a> → <a href="./topics/filesystem.html">WUFS</a></td></tr><tr><td>如何寫自己的互動程式？</td><td><a href="./topics/applications.html">Shell 與 fan</a></td></tr></tbody></table><h2 id="目前的系統邊界" tabindex="-1">目前的系統邊界 <a class="header-anchor" href="#目前的系統邊界" aria-label="Permalink to &quot;目前的系統邊界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>現況</th></tr></thead><tbody><tr><td>平台</td><td>QEMU virt、RV64、單核心、128 MiB RAM</td></tr><tr><td>執行模式</td><td>S-mode 核心、U-mode 使用者程式</td></tr><tr><td>行程</td><td>最多 4 個 PCB；fork／exec／exit／wait 與事件等待</td></tr><tr><td>排程</td><td>FIFO 就緒佇列、合作式切換，沒有計時器搶占</td></tr><tr><td>記憶體</td><td>Sv39 三級頁表、4 KiB 頁、按需分頁、FIFO 置換、獨立 Swap</td></tr><tr><td>磁碟</td><td>VirtIO 區塊 I/O、自訂 WUFS、重新啟動後保留檔案</td></tr><tr><td>操作</td><td>Shell、固定 writer | reader 管道、fan 全螢幕文字編輯器</td></tr></tbody></table><p>這是現有功能的實作紀錄，不是承諾與 Linux 相容。沒有一般磁碟 ELF 載入器、通用檔案描述號、網路或圖形桌面。</p><h2 id="這份文件如何組織" tabindex="-1">這份文件如何組織 <a class="header-anchor" href="#這份文件如何組織" aria-label="Permalink to &quot;這份文件如何組織&quot;">​</a></h2><p>主題章節描述目前設計；<a href="./history.html">原始規格與驗收紀錄</a> 保留開發過程。舊規格中的架構可能已被後續版本取代，閱讀時應留意每份文件的階段說明。</p><p>本站只展示架構說明與操作指令，OS 原始碼以 GitHub 連結提供，不內嵌程式碼。GitHub main 尚未提交的 Spec 10 改動，會在相關章節明確標示；本網站發布不會順帶提交 OS 修改。驗收結果是各規格所記錄的當時操作，網站建置不代表重新執行過 OS 驗證。</p><h2 id="參考與致意" tabindex="-1">參考與致意 <a class="header-anchor" href="#參考與致意" aria-label="Permalink to &quot;參考與致意&quot;">​</a></h2><p>閱讀版面與循序章節安排參考 <a href="https://operating-system-in-1000-lines.vercel.app/tw/" target="_blank" rel="noreferrer">《1000 行打造作業系統》</a>。本文內容依 WUWAOS 自己的程式碼整理，沒有複製該書文章。作業系統概念參考 repository 的 <code>notes/</code> 課程筆記，各章另列對應檔案；筆記全文不包含在網站中。</p>',14)])])}const f=a(o,[["render",i]]);export{m as __pageData,f as default};
